#!/usr/bin/env node

/**
 * Real-world test: stitch a reel from the latest generated images with
 * freshly generated NATURAL Ukrainian TTS voiceover matching the actual
 * latest digest and the on-screen pictures.
 *
 * The carousel images are generated by the image pipeline from a digest and
 * already carry their own baked-in NiSeNews design/text (so the generic
 * overlay is disabled).  This script:
 *   1. Loads the NEWEST digest by date from the pipeline SQLite DB
 *      (news-digest-pipeline/data/news-digest.db) — the same source the
 *      images were generated from.
 *   2. Parses its numbered news items.
 *   3. Synthesizes natural neural Ukrainian speech with edge-tts
 *      (uk-UA-PolinaNeural via uvx — free, no API key, neural quality).
 *   4. Times each clip to its own narration and stitches with music.
 */

import { generateShotClip } from './generate-clips.js';
import { prepareTtsText } from '../../lib/tts-pronunciation.js';
import { stitchClips, mergeShotVideoAndAudio } from './stitch.js';
import { readdirSync, writeFileSync, mkdirSync, existsSync } from 'fs';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';
import { execFileSync } from 'child_process';
import ffmpegStatic from 'ffmpeg-static';
import ffprobeStatic from 'ffprobe-static';
import { createRequire } from 'module';

const require = createRequire(import.meta.url);
const ffmpegStaticPkg = require('ffmpeg-static');
const ffprobeStaticPkg = require('ffprobe-static');

const FFMPEG = ffmpegStaticPkg || 'ffmpeg';
const FFPROBE = ffprobeStaticPkg.path;

const __dirname = dirname(fileURLToPath(import.meta.url));
const IMAGE_DIR = join(__dirname, '..', '..', 'image', 'output');
const OUTPUT_DIR = join(__dirname, '..', 'output');
const DB_PATH = join(__dirname, '..', '..', '..', 'data', 'news-digest.db');

const configuredEdgeVoice = process.env.EDGE_TTS_VOICE || '';
const EDGE_VOICE = /^uk-UA-/i.test(configuredEdgeVoice)
  ? configuredEdgeVoice
  : 'uk-UA-PolinaNeural';

function log(msg) {
  const ts = new Date().toISOString().slice(11, 19);
  console.log(`[${ts}] ${msg}`);
}

function getAudioDuration(audioPath) {
  return Number(execFileSync(FFPROBE, [
    '-v', 'error', '-show_entries', 'format=duration',
    '-of', 'default=noprint_wrappers=1:nokey=1', audioPath,
  ], { encoding: 'utf8' }).trim());
}

/**
 * Natural Ukrainian TTS via Microsoft Edge neural voices.
 * Uses uvx edge-tts (Python package, runs via `uvx` if uv is installed,
 * or via `pipx`/`python3 -m edge_tts`).  uk-UA-PolinaNeural sounds natural
 * and human — a major upgrade over the old synthetic Google Translate demo
 * voice.  Returns [{ audioPath, duration }].
 */
function generateUkrainianTTS(shots, tempDir) {
  const results = [];
  for (let i = 0; i < shots.length; i++) {
    const text = prepareTtsText(shots[i].spokenText || shots[i].headline || '');
    const mp3Path = join(tempDir, `audio_shot_${i + 1}.mp3`);
    const tmpPath = join(tempDir, `tts_raw_${i + 1}.mp3`);
    log(`  TTS ${i + 1}/${shots.length} (${EDGE_VOICE}): "${text.slice(0, 60)}..."`);

    // edge-tts CLI — pass text via --text= to avoid arg injection issues.
    execFileSync('uvx', [
      'edge-tts',
      `--text=${text}`,
      `--voice=${EDGE_VOICE}`,
      `--write-media=${tmpPath}`,
    ], { stdio: 'pipe' });

    // edge-tts emits 24kHz mono MP3; upconvert + stereo for the reel mix.
    execFileSync(FFMPEG, ['-y', '-i', tmpPath, '-ar', '48000', '-ac', '2', '-codec:a', 'libmp3lame', '-b:a', '192k', mp3Path], { stdio: 'pipe' });
    const duration = getAudioDuration(mp3Path);
    log(`  ✅ Ukrainian audio ${i + 1} ready (${duration.toFixed(2)}s)`);
    results.push({ audioPath: mp3Path, duration });
  }
  return results;
}

/**
 * Load the newest digest by DATE from the pipeline SQLite database and
 * parse its numbered news items ("1. text ...\nhttps://...").
 * Uses `sqlite3` CLI (available on macOS) to read content.
 * Returns [{ text, url }] in order.
 */
function loadLatestDigestItems() {
  if (!existsSync(DB_PATH)) {
    log(`Warning: DB not found at ${DB_PATH}`);
    return [];
  }

  // Order by date DESC so we get the truly newest digest (2026-08-02),
  // not whatever file sorts first alphabetically.
  let content = '';
  try {
    content = execFileSync('sqlite3', [
      DB_PATH,
      `SELECT content FROM digests ORDER BY date DESC LIMIT 1;`,
    ], { encoding: 'utf8' }).trim();
  } catch (err) {
    log(`Warning: could not query DB: ${err.message}`);
    return [];
  }

  if (!content) {
    log('Warning: latest digest is empty');
    return [];
  }

  // Cut off footer/disclaimer blocks.
  let clean = content.replace(/\n🤖[\s\S]*$/g, '');

  const items = [];
  const regex = /(\d+)\.\s+([\s\S]*?)(?=\n\d+\.\s|\n🤖|$)/g;
  let match;
  while ((match = regex.exec(clean)) !== null) {
    let body = match[2].trim();
    const urlMatch = body.match(/(https?:\/\/\S+)/);
    body = body.replace(/https?:\/\/\S+/g, '').trim();
    if (body.length > 40) {
      items.push({ text: body, url: urlMatch ? urlMatch[1] : null });
    }
  }

  log(`Parsed ${items.length} news items from newest DB digest`);
  return items;
}

/**
 * Convert a digest paragraph into a short spoken sentence (~40-150 chars)
 * for TTS: take the first sentence, drop fluff/emoji, cap the length.
 */
function toSpokenText(paragraph) {
  let s = paragraph
    .replace(/\s+/g, ' ')
    .replace(/[“”«»"']/g, '')
    .replace(/[\u{1F000}-\u{1FFFF}]/gu, '')
    .trim();

  // First sentence ending with . ! or ?
  const m = s.match(/^.*?[.!?](?:\s|$)/);
  if (m && m[0].length >= 30) {
    s = m[0].trim();
  }

  // Strip leading fluff phrases.
  s = s.replace(/^(Ну все,|Класика жанру:?|От і дожили:?|Особливо красиво,?|Особливо мило звучить,?|І це, звісно,?|Тобто)\s*/i, '');

  // Keep it speaking-friendly.
  if (s.length > 170) s = s.slice(0, 167).trimEnd() + '...';
  return s || paragraph.slice(0, 140);
}

async function main() {
  mkdirSync(OUTPUT_DIR, { recursive: true });
  const tempDir = join(OUTPUT_DIR, `temp_real_${Date.now()}`);
  mkdirSync(tempDir, { recursive: true });

  // Pick the newest non-empty Instagram carousel set. Its size is determined
  // by the selected digest and must not be hard-coded here.
  const instagramFiles = readdirSync(IMAGE_DIR)
    .filter(f => /^instagram_.*_\d+\.png$/.test(f));
  const batches = new Map();
  for (const filename of instagramFiles) {
    const match = filename.match(/^(instagram_.*)_\d+\.png$/);
    if (!match) continue;
    const prefix = match[1];
    if (!batches.has(prefix)) batches.set(prefix, []);
    batches.get(prefix).push(filename);
  }

  const latestBatch = [...batches.entries()]
    .filter(([, files]) => files.length > 0)
    .sort(([a], [b]) => a.localeCompare(b))
    .at(-1)?.[1]
    .sort((a, b) => Number(a.match(/_(\d+)\.png$/)[1]) - Number(b.match(/_(\d+)\.png$/)[1]));

  if (!latestBatch) {
    throw new Error('No Instagram carousel batch found in the image output directory.');
  }

  const images = latestBatch.map(filename => join(IMAGE_DIR, filename));

  log(`Using ${images.length} images:`);
  images.forEach(img => log(`  ${img}`));

  // Real content: load the newest digest (by date) from the pipeline DB —
  // the same source the images were generated from.
  const digestItems = loadLatestDigestItems();

  const spokenLines = [];
  for (let i = 0; i < images.length; i++) {
    if (digestItems[i]) {
      spokenLines.push(toSpokenText(digestItems[i].text));
    } else {
      spokenLines.push(`Новина ${i + 1} з останнього дайджесту NiSeNews.`);
    }
  }

  log('Voiceover lines from digest:');
  spokenLines.forEach((line, i) => log(`  ${i + 1}. ${line}`));

  const shots = images.map((img, i) => ({
    shot: i + 1,
    headline: spokenLines[i],
    spokenText: spokenLines[i],
    imageUrl: img,
    // Carousel images already contain their own baked-in NiSeNews design/text.
    // Adding the generic overlay again would double-up the text on the frame.
    overlay: false,
  }));

  // Generate natural neural Ukrainian TTS from the digest-derived text.
  log('Generating natural Ukrainian TTS voiceover from the latest digest...');
  const audioResults = generateUkrainianTTS(shots, tempDir);

  log('Generating clips synchronized with voiceover...');
  const clipPaths = [];
  for (let i = 0; i < shots.length; i++) {
    shots[i].duration = audioResults[i].duration;
    log(`  Shot ${i + 1}: ${audioResults[i].duration.toFixed(2)}s — "${shots[i].headline.slice(0, 50)}..."`);
    const silentPath = await generateShotClip(shots[i], tempDir);
    const syncedPath = join(tempDir, `shot_synced_${i + 1}.mp4`);
    mergeShotVideoAndAudio(silentPath, audioResults[i].audioPath, syncedPath);
    clipPaths.push(syncedPath);
  }

  log('Stitching final reel...');
  const timestamp = new Date().toISOString().slice(0, 19).replace(/[T:]/g, '-');
  const finalPath = join(OUTPUT_DIR, `reel_test_${timestamp}.mp4`);

  stitchClips({
    clipPaths,
    outputPath: finalPath,
    backgroundMusic: true,
  });

  log(`🎉 Real test reel created: ${finalPath}`);
}

main().catch(err => {
  console.error(err);
  process.exit(1);
});